{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Scale history embeddings by a fixed inverse-frequency feature computed solely from each category's training interactions. This may reduce frequent items' dominance while preserving learned embeddings, GRU topology, readout, scoring, loss and optimizer. The persistent buffer is restored by the existing generated predictor, which imports the same model class.",
      "edits": [
        {
          "find": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        dropout = dropout_rate if num_layers > 1 else 0.0",
          "replace": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        self.register_buffer(\"input_frequency_scale\", torch.ones(itemnum + 1))\n        self.input_frequency_scale[0] = 0.0\n        dropout = dropout_rate if num_layers > 1 else 0.0"
        },
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq) * self.input_frequency_scale[seq].unsqueeze(-1))"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq) * self.input_frequency_scale[seq].unsqueeze(-1))"
        },
        {
          "find": "    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)",
          "replace": "    counts = np.zeros(itemnum + 1, dtype=np.float64)\n    for history in user_train.values():\n        np.add.at(counts, np.asarray(history, dtype=np.int64), 1.0)\n    counts[0] = 0.0\n    observed = counts > 0\n    median_count = float(np.median(counts[observed]))\n    scales = np.full(itemnum + 1, 2.0, dtype=np.float32)\n    scales[observed] = np.clip(\n        (counts[observed] / median_count) ** (-0.15), 0.5, 2.0\n    ).astype(np.float32)\n    scales[0] = 0.0\n    with torch.no_grad():\n        model.input_frequency_scale.copy_(torch.from_numpy(scales).to(device))\n    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)"
        }
      ]
    }
  ],
  "change_summary": "Add checkpointed training-frequency input scales for all four category models. Apply identical scaling during training and inference; leave target embeddings and all training settings unchanged."
}
